{"format":"sql","data":"-- Database Export\n-- Generated on: 2026-06-01T03:23:59.816Z\n-- Format: SQL\n-- Include Data: true\n-- Row Limit: 1000 rows per table\n\n-- Table: audit_log\nCREATE TABLE IF NOT EXISTS audit_log (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, old_values jsonb, new_values jsonb, details text, created_at timestamptz NOT NULL DEFAULT now());\n\n-- Indexes for table: audit_log\nCREATE INDEX idx_audit_log_action ON public.audit_log USING btree (action);\nCREATE INDEX idx_audit_log_created_at ON public.audit_log USING btree (created_at DESC);\nCREATE INDEX idx_audit_log_entity_id ON public.audit_log USING btree (entity_id) WHERE (entity_id IS NOT NULL);\nCREATE INDEX idx_audit_log_entity_type ON public.audit_log USING btree (entity_type);\nCREATE INDEX idx_audit_log_user_id ON public.audit_log USING btree (user_id);\n\n-- RLS enabled for table: audit_log\nALTER TABLE audit_log ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: audit_log\nCREATE POLICY audit_log_select_admin ON audit_log FOR SELECT TO authenticated USING ((get_user_role() = 'admin'::text));\nCREATE POLICY project_admin_policy ON audit_log FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Data for table: audit_log\nINSERT INTO audit_log (id, user_id, action, entity_type, entity_id, old_values, new_values, details, created_at) VALUES ('9283f633-9a14-42b4-a0e5-220863e5f016', NULL, 'LOGOUT', 'auth_session', NULL, NULL, NULL, 'Cierre de sesión', '2026-06-01T03:04:20.032Z');\nINSERT INTO audit_log (id, user_id, action, entity_type, entity_id, old_values, new_values, details, created_at) VALUES ('10b91b80-ac15-4b8e-8b90-e5ef2b01e34a', '57f9fe08-96ec-450c-b95f-ef509d592551', 'LOGIN', 'auth_session', NULL, NULL, NULL, 'Inicio de sesión: admin@plantalimentos.ec', '2026-06-01T03:04:23.203Z');\nINSERT INTO audit_log (id, user_id, action, entity_type, entity_id, old_values, new_values, details, created_at) VALUES ('0da8c3f1-cede-44b6-9ba8-dc0343dbc0fc', '57f9fe08-96ec-450c-b95f-ef509d592551', 'LOGIN', 'auth_session', NULL, NULL, NULL, 'Inicio de sesión: admin@plantalimentos.ec', '2026-06-01T03:22:40.513Z');\n\n-- Table: categories\nCREATE TABLE IF NOT EXISTS categories (id uuid NOT NULL DEFAULT gen_random_uuid(), name text NOT NULL, description text, created_at timestamptz NOT NULL DEFAULT now());\n\n-- Indexes for table: categories\nCREATE UNIQUE INDEX categories_name_key ON public.categories USING btree (name);\n\n-- RLS enabled for table: categories\nALTER TABLE categories ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: categories\nCREATE POLICY categories_delete_admin ON categories FOR DELETE TO authenticated USING ((get_user_role() = 'admin'::text));\nCREATE POLICY categories_insert_admin ON categories FOR INSERT TO authenticated WITH CHECK ((get_user_role() = 'admin'::text));\nCREATE POLICY categories_select_all ON categories FOR SELECT TO public USING (true);\nCREATE POLICY categories_update_admin ON categories FOR UPDATE TO authenticated USING ((get_user_role() = 'admin'::text));\nCREATE POLICY project_admin_policy ON categories FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: inventory_ledger\nCREATE TABLE IF NOT EXISTS inventory_ledger (id uuid NOT NULL DEFAULT gen_random_uuid(), product_id uuid NOT NULL, lot_id uuid, movement_type USER-DEFINED NOT NULL, quantity numeric NOT NULL, unit_cost numeric DEFAULT 0, reference_type text, reference_id uuid, notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), supplier_id uuid);\n\n-- Indexes for table: inventory_ledger\nCREATE INDEX idx_ledger_created_at ON public.inventory_ledger USING btree (created_at DESC);\nCREATE INDEX idx_ledger_lot ON public.inventory_ledger USING btree (lot_id);\nCREATE INDEX idx_ledger_product ON public.inventory_ledger USING btree (product_id);\nCREATE INDEX idx_ledger_reference ON public.inventory_ledger USING btree (reference_type, reference_id);\nCREATE INDEX idx_ledger_supplier ON public.inventory_ledger USING btree (supplier_id);\n\n-- Foreign key constraints for table: inventory_ledger\nALTER TABLE inventory_ledger ADD CONSTRAINT inventory_ledger_lot_id_fkey FOREIGN KEY (lot_id) REFERENCES lots (id) ON DELETE SET NULL;\nALTER TABLE inventory_ledger ADD CONSTRAINT inventory_ledger_product_id_fkey FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT;\nALTER TABLE inventory_ledger ADD CONSTRAINT inventory_ledger_supplier_id_fkey FOREIGN KEY (supplier_id) REFERENCES suppliers (id) ON DELETE SET NULL;\n\n-- RLS enabled for table: inventory_ledger\nALTER TABLE inventory_ledger ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: inventory_ledger\nCREATE POLICY ledger_insert_kiosk ON inventory_ledger FOR INSERT TO authenticated WITH CHECK ((get_user_role() = 'sales_kiosk'::text));\nCREATE POLICY ledger_insert_production_trigger ON inventory_ledger FOR INSERT TO authenticated WITH CHECK (((reference_type = 'PRODUCCION'::text) AND (get_user_role() = ANY (ARRAY['admin'::text, 'operario'::text]))));\nCREATE POLICY ledger_insert_staff ON inventory_ledger FOR INSERT TO authenticated WITH CHECK ((get_user_role() = ANY (ARRAY['admin'::text, 'operario'::text])));\nCREATE POLICY ledger_select_staff ON inventory_ledger FOR SELECT TO authenticated USING ((get_user_role() = ANY (ARRAY['admin'::text, 'operario'::text])));\nCREATE POLICY project_admin_policy ON inventory_ledger FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Triggers for table: inventory_ledger\nCREATE TRIGGER trg_enforce_finished_ingress BEFORE INSERT ON inventory_ledger FOR EACH ROW EXECUTE FUNCTION enforce_finished_product_ingress();\n\n-- Data for table: inventory_ledger\nINSERT INTO inventory_ledger (id, product_id, lot_id, movement_type, quantity, unit_cost, reference_type, reference_id, notes, created_by, created_at, supplier_id) VALUES ('b22fb7c0-2ce4-48df-94a8-2f9991c38a25', 'f3f9643b-9bfb-4d4e-bf