straints for table: lots\nALTER TABLE lots ADD CONSTRAINT lots_product_id_fkey FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: lots\nALTER TABLE lots ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: lots\nCREATE POLICY lots_insert_staff ON lots FOR INSERT TO authenticated WITH CHECK ((get_user_role() = ANY (ARRAY['admin'::text, 'operario'::text])));\nCREATE POLICY lots_select_staff ON lots FOR SELECT TO authenticated USING ((get_user_role() = ANY (ARRAY['admin'::text, 'operario'::text])));\nCREATE POLICY lots_update_staff ON lots FOR UPDATE TO authenticated USING ((get_user_role() = ANY (ARRAY['admin'::text, 'operario'::text])));\nCREATE POLICY project_admin_policy ON lots FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: order_items\nCREATE TABLE IF NOT EXISTS order_items (id uuid NOT NULL DEFAULT gen_random_uuid(), order_id uuid NOT NULL, product_id uuid NOT NULL, quantity numeric NOT NULL, unit_price numeric NOT NULL, subtotal numeric NOT NULL, created_at timestamptz NOT NULL DEFAULT now());\n\n-- Indexes for table: order_items\nCREATE INDEX idx_order_items_order ON public.order_items USING btree (order_id);\n\n-- Foreign key constraints for table: order_items\nALTER TABLE order_items ADD CONSTRAINT order_items_order_id_fkey FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE;\nALTER TABLE order_items ADD CONSTRAINT order_items_product_id_fkey FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT;\n\n-- RLS enabled for table: order_items\nALTER TABLE order_items ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: order_items\nCREATE POLICY order_items_insert_client ON order_items FOR INSERT TO authenticated WITH CHECK ((EXISTS ( SELECT 1\n   FROM orders o\n  WHERE ((o.id = order_items.order_id) AND (o.user_id = auth.uid())))));\nCREATE POLICY order_items_insert_kiosk ON order_items FOR INSERT TO authenticated WITH CHECK (((get_user_role() = 'sales_kiosk'::text) AND (EXISTS ( SELECT 1\n   FROM orders o\n  WHERE ((o.id = order_items.order_id) AND (o.user_id = auth.uid()))))));\nCREATE POLICY order_items_select ON order_items FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1\n   FROM orders o\n  WHERE ((o.id = order_items.order_id) AND ((o.user_id = auth.uid()) OR (get_user_role() = ANY (ARRAY['admin'::text, 'operario'::text])))))));\nCREATE POLICY project_admin_policy ON order_items FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Data for table: order_items\nINSERT INTO order_items (id, order_id, product_id, quantity, unit_price, subtotal, created_at) VALUES ('e5c71457-98c3-40ee-8b58-9d7923478e9d', '3a467b53-387a-4487-b987-fbb52cc8c50a', '2a9b8d98-4f6a-40a5-8b37-fa28838b4085', '1.0000', '8.50', '8.50', '2026-05-19T00:31:38.572Z');\nINSERT INTO order_items (id, order_id, product_id, quantity, unit_price, subtotal, created_at) VALUES ('7975a9b9-966b-4bad-949d-2a2acc08462c', '3a467b53-387a-4487-b987-fbb52cc8c50a', '88743e15-fba1-4377-b810-a5af6146c934', '2.0300', '4.50', '9.14', '2026-05-19T00:31:38.572Z');\nINSERT INTO order_items (id, order_id, product_id, quantity, unit_price, subtotal, created_at) VALUES ('ee091e7d-e833-42c5-9dfd-fc1b8dd3081f', 'b32a1d39-0a67-4ef0-8820-4e44630aed47', '2a9b8d98-4f6a-40a5-8b37-fa28838b4085', '2.0000', '8.50', '17.00', '2026-05-19T00:38:22.152Z');\nINSERT INTO order_items (id, order_id, product_id, quantity, unit_price, subtotal, created_at) VALUES ('e1a3bb29-1726-4b6c-9a8d-4218090f17a3', '463c2eb5-c3ba-4d46-b061-a210437d47ff', '2a9b8d98-4f6a-40a5-8b37-fa28838b4085', '2.0000', '8.50', '17.00', '2026-05-19T01:23:02.601Z');\nINSERT INTO order_items (id, order_id, product_id, quantity, unit_price, subtotal, created_at) VALUES ('6ee3740b-d189-4c5b-81c4-776c6e1abd83', '463c2eb5-c3ba-4d46-b061-a210437d47ff', '88743e15-fba1-4377-b810-a5af6146c934', '2.0000', '4.50', '9.00', '2026-05-19T01:23:02.601Z');\nINSERT INTO order_items (id, order_id, product_id, quantity, unit_price,