ADD CONSTRAINT packaging_orders_production_order_id_fkey FOREIGN KEY (production_order_id) REFERENCES production_orders (id) ON DELETE SET NULL;\nALTER TABLE packaging_orders ADD CONSTRAINT packaging_orders_template_id_fkey FOREIGN KEY (template_id) REFERENCES packaging_templates (id) ON DELETE RESTRICT;\n\n-- RLS enabled for table: packaging_orders\nALTER TABLE packaging_orders ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: packaging_orders\nCREATE POLICY pkg_orders_insert_staff ON packaging_orders FOR INSERT TO authenticated WITH CHECK ((get_user_role() = ANY (ARRAY['admin'::text, 'operario'::text])));\nCREATE POLICY pkg_orders_select_staff ON packaging_orders FOR SELECT TO authenticated USING ((get_user_role() = ANY (ARRAY['admin'::text, 'operario'::text])));\nCREATE POLICY pkg_orders_update_staff ON packaging_orders FOR UPDATE TO authenticated USING ((get_user_role() = ANY (ARRAY['admin'::text, 'operario'::text])));\nCREATE POLICY project_admin_policy ON packaging_orders FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Triggers for table: packaging_orders\nCREATE TRIGGER set_packaging_orders_updated_at BEFORE UPDATE ON packaging_orders FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER trg_audit_packaging_orders AFTER UPDATE ON packaging_orders FOR EACH ROW EXECUTE FUNCTION audit_packaging_orders_update();\nCREATE TRIGGER trg_packaging_completion BEFORE UPDATE ON packaging_orders FOR EACH ROW EXECUTE FUNCTION fn_packaging_completion();\n\n-- Data for table: packaging_orders\nINSERT INTO packaging_orders (id, template_id, production_order_id, units_to_package, bulk_quantity_consumed, status, batch_number, notes, completed_at, created_by, created_at, updated_at) VALUES ('bcdfb096-94e3-4a8c-b8ee-f7859c76ae94', '08c7e657-5680-4fdb-a39a-99b715c361ab', '0b6ab587-1c60-4699-8840-229363c95716', '5.0000', '5000.0000', 'COMPLETADA', 'EMP-2026-0011', 'Vinculado a lote de producción', '2026-05-26T01:36:10.987Z', NULL, '2026-05-26T01:29:17