);\nCREATE POLICY products_update_staff ON products FOR UPDATE TO authenticated USING ((get_user_role() = ANY (ARRAY['admin'::text, 'operario'::text])));\nCREATE POLICY project_admin_policy ON products FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Triggers for table: products\nCREATE TRIGGER set_products_updated_at BEFORE UPDATE ON products FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER trg_audit_products_update AFTER UPDATE ON products FOR EACH ROW EXECUTE FUNCTION audit_products_update();\nCREATE TRIGGER trg_prevent_product_type_change BEFORE UPDATE ON products FOR EACH ROW EXECUTE FUNCTION prevent_product_type_change();\n\n-- Data for table: products\nINSERT INTO products (id, name, sku, type, unit, category_id, description, price, image_url, is_active, created_at, updated_at, short_description, long_description, specifications, ingredients, nutritional_info, weight, commercial_details, featured, conversion_factor, sales_unit_name, min_stock_alert, cost_per_unit, capacity) VALUES ('3ebdecab-48e7-4353-aaf1-74c66a757077', 'Harina', 'HG-001', 'MATERIA_PRIMA', 'kg', NULL, NULL, '3.00', NULL, true, '2026-04-29T23:32:51.256Z', '2026-04-29T23:32:51.256Z', NULL, NULL, '{}', NULL, '{}', NULL, NULL, false, 1, NULL, NULL, '0.0000', NULL);\nINSERT INTO products (id, name, sku, type, unit, category_id, description, price, image_url, is_active, created_at, updated_at, short_description, long_description, specifications, ingredients, nutritional_info, weight, commercial_details, featured, conversion_factor, sales_unit_name, min_stock_alert, cost_per_unit, capacity) VALUES ('f55c0e8a-fa6a-46f4-b290-cf39d5fa17a9', 'Miel', 'MSH-001', 'MATERIA_PRIMA', 'ml', NULL, NULL, '0.00', NULL, true, '2026-05-11T03:14:04.996Z', '2026-05-11T03:14:04.996Z', NULL, NULL, '{}', NULL, '{}', NULL, NULL, false, 1, NULL, NULL, '0.0000', NULL);\nINSERT INTO products (id, name, sku, type, unit, category_id, description, price, image_url, is_active, created_at, updated_at